// Extract SQL from whatever the previous node returned (handles both success and error cases)
const item = $input.item.json;

// Get raw text from wherever it might be (success output or error message)
let rawText = '';
if (item.error) {
  rawText = typeof item.error === 'string' ? item.error : JSON.stringify(item.error);
} else {
  rawText = item.output || item.text || item.sql || JSON.stringify(item);
}

// Try to extract SQL regardless of surrounding JSON/text/markdown
let sql;
const jsonMatch = rawText.match(/\{[\s\S]*"sql"\s*:\s*"([\s\S]*?)"\s*\}/);
if (jsonMatch) {
  sql = jsonMatch[1].replace(/\\"/g, '"').replace(/\\n/g, ' ');
} else {
  const selectMatch = rawText.match(/(SELECT|WITH)[\s\S]*/i);
  sql = selectMatch ? selectMatch[0] : null;
}

if (!sql) {
  return [{
    json: {
      success: false,
      valid: false,
      error: "Could not extract SQL from model output.",
      sql: null
    }
  }];
}

// Destructive commands to block
const destructivePatterns = [
  /\bDROP\b/i,
  /\bDELETE\b/i,
  /\bTRUNCATE\b/i,
  /\bALTER\b/i,
  /\bUPDATE\b/i,
  /\bINSERT\b/i,
  /\bCREATE\b/i,
  /\bGRANT\b/i,
  /\bREVOKE\b/i,
  /;.*SELECT/i,  // Multiple statements
  /--/,  // SQL comments
  /\/\*/  // Block comments
];

// Check for destructive patterns
for (const pattern of destructivePatterns) {
  if (pattern.test(sql)) {
    return [{
      json: {
        success: false,
        valid: false,
        error: "Query contains unauthorized operations. Only SELECT queries are allowed.",
        sql: sql
      }
    }];
  }
}

// Validate starts with SELECT
const trimmedSql = sql.trim().toUpperCase();
if (!trimmedSql.startsWith('SELECT') && !trimmedSql.startsWith('WITH')) {
  return [{
    json: {
      success: false,
      valid: false,
      error: "Query must be a SELECT statement.",
      sql: sql
    }
  }];
}

// Query is valid
return [{
  json: {
    success: true,
    valid: true,
    sql: sql.trim(),
    query_description: $input.item.json.query_description
  }
}];

// Check if we came from error path (from the False branch of Valid?)
if ($input.item.json.valid === false) {
  return [{
    json: {
      success: false,
      error: $input.item.json.error,
      sql: $input.item.json.sql
    }
  }];
}

// Check if query execution failed
if ($input.item.json.error) {
  return [{
    json: {
      success: false,
      error: `Database error: ${$input.item.json.error}`,
      sql: $input.item.json.sql
    }
  }];
}

// Get ALL items from PostgreSQL (each row is a separate item in N8N)
const allItems = $input.all();

// Check if query returned no results
if (!allItems || allItems.length === 0) {
  return [{
    json: {
      success: true,
      data: {
        headers: [],
        rows: []
      },
      row_count: 0,
      sql_executed: $node["Query Validation"].json.sql,
      message: "Query executed successfully but returned no results."
    }
  }];
}

// Extract results from all items
const results = allItems.map(item => item.json);

// Extract headers and rows
const headers = Object.keys(results[0]);
const rows = results.map(row => headers.map(h => row[h]));

// Return formatted response
return [{
  json: {
    success: true,
    data: {
      headers: headers,
      rows: rows
    },
    row_count: results.length,
    sql_executed: $node["Query Validation"].json.sql
  }
}];
